 35	final class DirectedGraph {
 36	    private final List<List<Integer>> adjacencyList;
 37	    private final int[] indegree;
 38	
 39	    private DirectedGraph(List<List<Integer>> adjacencyList, int[] indegree) {
 40	        this.adjacencyList = adjacencyList;
 41	        this.indegree = indegree;
 42	    }
 43	
 44	    public static Builder builder(int vertexCount) {
 45	        return new Builder(vertexCount);
 46	    }
 47	
 48	    public static DirectedGraph fromAdjacencyList(List<List<Integer>> adjacencyList) {
 49	        Builder graph = builder(adjacencyList.size());
 50	        for (int source = 0; source < adjacencyList.size(); source++) {
 51	            for (int destination : adjacencyList.get(source)) {
 52	                graph.addEdge(source, destination);
 53	            }
 54	        }
 55	        return graph.build();
 56	    }
 57	
 58	    public boolean hasCycle() {
 59	        return DetectCycleDirectedGraph.hasCycle(this);
 60	    }
 61	
 62	    public int vertexCount() {
 63	        return adjacencyList.size();
 64	    }
 65	
 66	    public List<Integer> neighborsOf(int vertex) {
 67	        validateVertex(vertex);
 68	        return adjacencyList.get(vertex);
 69	    }
 70	
 71	    public int[] indegreeSnapshot() {
 72	        return indegree.clone();
 73	    }
 74	
 75	    private void validateVertex(int vertex) {
 76	        validateVertex(vertex, adjacencyList.size());
 77	    }
 78	
 79	    private static void validateVertex(int vertex, int vertexCount) {
 80	        if (vertex < 0 || vertex >= vertexCount) {
 81	            throw new IndexOutOfBoundsException(
 82	                    "Invalid vertex: " + vertex + " for graph size " + vertexCount);
 83	        }
 84	    }
 85	
 86	    public static final class Builder {
 87	        private final List<List<Integer>> adjacencyList;
 88	        private final int[] indegree;
 89	
 90	        private Builder(int vertexCount) {
 91	            if (vertexCount < 0) {
 92	                throw new IllegalArgumentException("vertexCount must be non-negative");
 93	            }
 94	
 95	            adjacencyList = new ArrayList<>(vertexCount);
 96	            indegree = new int[vertexCount];
 97	            for (int vertex = 0; vertex < vertexCount; vertex++) {
 98	                adjacencyList.add(new ArrayList<>());
 99	            }
100	        }
101	
102	        public Builder addEdge(int source, int destination) {
103	            validateVertex(source, adjacencyList.size());
104	            validateVertex(destination, adjacencyList.size());
105	            adjacencyList.get(source).add(destination);
106	            indegree[destination]++;
107	            return this;
108	        }
109	
110	        public DirectedGraph build() {
111	            List<List<Integer>> immutableAdjacencyList = new ArrayList<>(adjacencyList.size());
112	            for (List<Integer> neighbors : adjacencyList) {
113	                immutableAdjacencyList.add(Collections.unmodifiableList(new ArrayList<>(neighbors)));
114	            }
115	
116	            return new DirectedGraph(
117	                    Collections.unmodifiableList(immutableAdjacencyList),
118	                    indegree.clone());
119	        }
120	    }
121	}
