123	final class CycleDetector {
124	    private final DirectedGraph graph;
125	    private final int[] indegree;
126	    private final Queue<Integer> zeroIndegreeVertices;
127	    private int visitedCount;
128	
129	    CycleDetector(DirectedGraph graph) {
130	        this.graph = graph;
131	        this.indegree = graph.indegreeSnapshot();
132	        this.zeroIndegreeVertices = collectZeroIndegreeVertices(indegree);
133	    }
134	
135	    boolean hasCycle() {
136	        while (!zeroIndegreeVertices.isEmpty()) {
137	            processNextVertex();
138	        }
139	        return visitedCount != graph.vertexCount();
140	    }
141	
142	    private void processNextVertex() {
143	        int vertex = zeroIndegreeVertices.poll();
144	        visitedCount++;
145	
146	        for (int neighbor : graph.neighborsOf(vertex)) {
147	            decrementIndegree(neighbor);
148	        }
149	    }
150	
151	    private void decrementIndegree(int vertex) {
152	        indegree[vertex]--;
153	        if (indegree[vertex] == 0) {
154	            zeroIndegreeVertices.add(vertex);
155	        }
156	    }
157	
158	    private static Queue<Integer> collectZeroIndegreeVertices(int[] indegree) {
159	        Queue<Integer> queue = new ArrayDeque<>();
160	        for (int vertex = 0; vertex < indegree.length; vertex++) {
161	            if (indegree[vertex] == 0) {
162	                queue.add(vertex);
163	            }
164	        }
165	        return queue;
166	    }
167	}
